style.css:
body {
  background-color: #000c18;
  color: #ffffff;
}

h1, h2, h3, h4, h5, h6 {
  color: #ff9d00;
}

a {
  color: #89ddff;
}

code, pre {
  background-color: #001a2e;
  color: #a5ff90;
}

blockquote {
  border-left: 4px solid #5c6773;
  color: #5c6773;
}

hr {
  border-top: 1px solid #5c6773;
}

th {
  background-color: #001a2e;
  color: #82aaff;
}

td {
  background-color: #000f1f;
}
